      "calibration": 4,
      "coherence": 4,
      "correctness": 4,
      "grounding": 4,
      "instruction_following": 2,
      "usefulness": 4
    },
    "B": {
      "calibration": 4,
      "coherence": 4,
      "correctness": 4,
      "grounding": 4,
